Someone golfed our CSV of IDs into NaN. Save /workspace/ids.mjs:

export function parseIds(csv) {
  return csv.split(",").map(parseInt);
}

parseIds("1,7,11") returns [1, NaN, 3] because map passes the index as parseInt's radix. Write ids.test.mjs first (node:test) asserting parseIds("1,7,11") deep-equals [1, 7, 11] and parseIds("10,010") deep-equals [10, 10]; run and confirm the NaN. Fix with an explicit arrow and Number or parseInt(s, 10), trim whitespace around entries, and make empty entries throw a TypeError naming the bad index. Add tests for " 4 , 5 " and for the throwing case ("1,,2"). node --test must pass.

tools_list = await mcp.list_tools("tools")
for t in tools_list:
    print(t["name"], t["inputSchema"])

arguments.code:
result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/ids.test.mjs", "content": "import { test } from "node:test";
import assert from "node:assert/strict";
import { parseIds } from "./ids.mjs";

test('parseIds("1,7,11") deep-equals [1, 7, 11]', () => {
  assert.deepEqual(parseIds("1,7,11"), [1, 7, 11]);
});

test('parseIds("10,010") deep-equals [10, 10]', () => {
  assert.deepEqual(parseIds("10,010"), [10, 10]);
});

test('whitespace around entries is trimmed: parseIds(" 4 , 5 ") -> [4, 5]', () => {
  assert.deepEqual(parseIds(" 4 , 5 "), [4, 5]);
});

test("empty entry throws TypeError naming the bad index", () => {
  assert.throws(
    () => parseIds("1,,2"),
    (err) =>
      err instanceof TypeError &&
      err.message.includes("index 1"),
  );
});
"})
print(result)

