result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/ids.mjs", "content": "export function parseIds(csv) {
  return csv.split(",").map((entry, i) => {
    const s = entry.trim();
    if (s === "") {
      throw new TypeError(
        `parseIds: empty entry at index ${i} of "${csv}"`,
      );
    }
    return parseInt(s, 10);
  });
}
"})
print(result)
